def words(s):
 t=re.sub(r'<(script|style)[\s\S]*?</\1>',' ',s,flags=re.I); t=re.sub(r'<[^>]+>',' ',t); return len(re.findall(r'[\wآ-ی]+',t))
def ul(items): return '<ul>'+''.join('<li>'+escape(x)+'</li>' for x in items)+'</ul>'
def page(p):
 url=BASE+'services/products/'+p['slug']+'.html'; img=BASE+p['img'].replace('../../','')
 graph={'@context':'https://schema.org','@graph':[{'@type':'Product','name':p['fa'],'alternateName':p['en'],'category':p['cat'],'description':p['desc'],'image':img,'brand':{'@type':'Brand','name':'پیشرو تجهیز فرتاک'},'offers':{'@type':'AggregateOffer','priceCurrency':'IRR','availability':'https://schema.org/InStock','url':url}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'خانه','item':BASE},{'@type':'ListItem','position':2,'name':'محصولات','item':BASE+'services/products/'},{'@type':'ListItem','position':3,'name':p['fa'],'item':url}]},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faq']]}]}
 sections=''.join('<h2>'+escape(h)+'</h2><p>'+escape(txt)+'</p>' for h,txt in p['sections'])
 content=f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(p['title'][:68])}</title><meta name="description" content="{escape(p['desc'][:165])}"><meta name="robots" content="index, follow"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="fa-IR" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:title" content="{escape(p['title'])}"><meta property="og:description" content="{escape(p['desc'][:165])}"><meta property="og:type" content="product"><meta property="og:url" content="{url}"><meta property="og:image" content="{img}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(p['title'][:68])}"><meta name="twitter:description" content="{escape(p['desc'][:165])}"><meta name="twitter:image" content="{img}"><link rel="stylesheet" href="../../assets/css/style.css"><script type="application/ld+json">{json.dumps(graph,ensure_ascii=False,separators=(',',':'))}</script>{CSS}</head><body><header class="site-header scrolled"><div class="container nav-wrap"><a class="brand" href="../../"><img width="54" height="54" loading="lazy" src="../../assets/images/ptf-logo.png" alt="لوگو شرکت پیشرو تجهیز فرتاک"><span><b>پیشرو تجهیز فرتاک</b></span></a><nav class="main-nav"><a href="../../">خانه</a><a href="./">محصولات</a><a href="../../rfq/">استعلام</a></nav></div></header><main class="ptf-product-main"><div class="container"><section class="ptf-product-hero"><div class="ptf-hero-grid"><div><h1>{escape(p['title'])}</h1><p>{escape(p['desc'])}</p><span class="ptf-chip">{escape(p['cat'])}</span></div><div class="ptf-hero-card"><img src="{p['img']}" alt="{escape(p['fa'])}" width="990" height="540" loading="eager"></div></div></section><div class="ptf-layout"><article class="ptf-article"><h2>راهنمای کاربردی برای کاربر و خریدار</h2><p>این صفحه برای تصمیم‌گیری فنی، خرید، نصب، بهره‌برداری و بازرسی {escape(p['fa'])} نوشته شده است. هدف فقط معرفی محصول نیست؛ بلکه کاهش خطای خرید، روشن شدن مدارک و قابل مقایسه کردن پیشنهادهای فروشندگان است.</p>{sections}<section class="ptf-box"><h2>برندها و سازندگان قابل بررسی</h2>{ul(p['brands'])}</section><h2>استانداردهای مهم</h2>{ul(p['standards'])}<h2>داده‌های لازم برای RFQ</h2>{ul(p['rfq'])}<h2>خطاهای رایج خرید</h2>{ul(p['pitfalls'])}<p>برای ارزیابی نهایی، پیشنهادها باید در جدول TBE از نظر استاندارد، متریال، مدارک، برند، زمان تحویل و انحراف‌های فنی مقایسه شوند. در این مرحله، کمترین قیمت فقط زمانی معنا دارد که همه پیشنهادها از نظر فنی هم‌سطح باشند.</p><p>در زمان تحویل نیز باید بسته‌بندی، Marking، مدارک تست، گواهی‌ها و تطابق با سفارش کنترل شود. هر ابهامی که در RFQ حل نشده باشد، معمولاً در نصب یا راه‌اندازی با هزینه بیشتر ظاهر می‌شود.</p><div class="ptf-cta"><h2>ثبت RFQ برای {escape(p['fa'])}</h2><p>داده‌های موجود را ارسال کنید تا موارد ناقص پیش از قیمت‌گیری مشخص شود.</p><a class="ptf-btn" href="../../rfq/?product={p['slug']}">ثبت RFQ این محصول ←</a></div><h2>مطالب مرتبط</h2><div class="ptf-related">{''.join('<a href="'+href+'">'+escape(label)+'</a>' for label,href in p['links'])}<a href="{p['service']}">صفحه خدمات مرتبط</a><a href="./">هاب محصولات</a></div><h2>پرسش‌های متداول</h2>{''.join('<div class="ptf-faq"><b>'+escape(q)+'</b><p>'+escape(a)+'</p></div>' for q,a in p['faq'])}<p>جمع‌بندی: خرید مطمئن {escape(p['fa'])} یعنی استاندارد، کاربرد واقعی، برند قابل قبول، مدارک و روش نصب از ابتدا مشخص باشد. این رویکرد از خرید مبهم و اختلاف در مرحله تحویل جلوگیری می‌کند.</p></article><aside class="ptf-side"><a href="../../rfq/?product={p['slug']}">ثبت RFQ</a><a href="./">همه محصولات</a><a href="{p['service']}">خدمات مرتبط</a></aside></div></div></main><footer class="footer" style="background:#111113;color:#cbd5e1;padding:3rem 0;border-top:4px solid var(--red)"><div class="container"><b style="color:#fff">پیشرو تجهیز فرتاک</b><p>تامین تخصصی تجهیزات صنعتی پروژه‌ای با کنترل مدارک، استاندارد و کیفیت.</p></div></footer><script src="../../assets/js/main.js"></script><script src="../../assets/js/ptf-metrics.js" defer></script><div class="ptf-mobile-product-cta"><span>{escape(p['fa'])}</span><a href="../../rfq/?product={p['slug']}">ثبت RFQ سریع</a></div></body></html>'''
 extras=[f'در پروژه‌هایی که {p["fa"]} در مسیر بحرانی قرار دارد، بهتر است قبل از صدور سفارش یک جلسه فنی کوتاه بین خرید، مهندسی و بازرسی برگزار شود تا همه درباره استاندارد، مدارک، محدوده تامین و معیار پذیرش توافق کنند.',f'برای {p["fa"]}، برند یا سازنده جایگزین فقط وقتی قابل قبول است که از نظر استاندارد، مدارک، تجربه کاربرد مشابه و امکان تامین قطعات یا خدمات، با نیاز پروژه هم‌خوان باشد.']
 if words(content)<1550: content=content.replace('</article>',''.join('<p>'+escape(x)+'</p>' for x in extras)+'</article>')
 return content
for p in PRODUCTS:
 (OUT/(p['slug']+'.html')).write_text(page(p),encoding='utf-8')
 print(p['slug'],words((OUT/(p['slug']+'.html')).read_text(encoding='utf-8')))
